// Health-check workflow — runs every 10 min, checks the sovereign loop.
//
// Checks (early-exit-on-fail per check, but always run all of them):
//   1. n8n /healthz responds locally
//   2. Workflow 15 wrote a _balance.json in last 24h (bank ingest fresh)
//   3. Workflow 16's reconcile state updated in last 90 min
//   4. Disk free on /volume1 > 5GB
//   5. Active workflow count from filesystem (via /data marker if present)
//
// Records every run to /data/finance-events/_health/<timestamp>.json so the
// briefing workflow can surface the latest run state.
//
// Severity transitions trigger ntfy. Ongoing failures re-alert every 6h.
// See docs/99-session-notes/2026-05-28-brief-health-check.md for full spec.

const fs = require('fs');
const path = require('path');
const http = require('http');

const HEALTH_DIR = '/data/finance-events/_health';
const BANK_ROOT = '/data/finance-events/bank';
const RECONCILE_STATE_FILES = [
  '/data/chatin/_reconcile_state.json',
  '/data/finance-events/_reconcile_state.json'
];
const NTFY_HOST = process.env.NTFY_HOST || 'ntfy';
const NTFY_PORT = parseInt(process.env.NTFY_PORT || '80', 10);
const NTFY_TOPIC = process.env.NTFY_TOPIC || 'poetech-health';

try { fs.mkdirSync(HEALTH_DIR, { recursive: true }); } catch (_) {}

function now() { return new Date().toISOString(); }
function nowMs() { return Date.now(); }
function safeStat(p) { try { return fs.statSync(p); } catch (_) { return null; } }
function safeReadJson(p) { try { return JSON.parse(fs.readFileSync(p, 'utf8')); } catch (_) { return null; } }

async function localHttpGet(urlPath) {
  return new Promise(resolve => {
    const req = http.get({ host: '127.0.0.1', port: 5678, path: urlPath, timeout: 3000 }, res => {
      resolve({ ok: res.statusCode >= 200 && res.statusCode < 400, status: res.statusCode });
    });
    req.on('error', () => resolve({ ok: false, status: 0 }));
    req.on('timeout', () => { req.destroy(); resolve({ ok: false, status: 0, timeout: true }); });
  });
}

async function checkN8n() {
  const r = await localHttpGet('/healthz');
  return { name: 'n8n_health', ok: r.ok, detail: 'HTTP ' + r.status };
}

function checkWf15Fresh() {
  // Find the freshest _balance.json under bank/*/.
  let freshest = 0;
  let dirs;
  try { dirs = fs.readdirSync(BANK_ROOT); } catch (_) { return { name: 'wf15_fresh', ok: false, detail: 'bank dir missing' }; }
  for (const d of dirs) {
    const p = path.join(BANK_ROOT, d, '_balance.json');
    const s = safeStat(p);
    if (s && s.mtimeMs > freshest) freshest = s.mtimeMs;
  }
  if (freshest === 0) return { name: 'wf15_fresh', ok: false, detail: 'no _balance.json found' };
  const ageHours = (nowMs() - freshest) / 3_600_000;
  return { name: 'wf15_fresh', ok: ageHours < 36, detail: ageHours.toFixed(1) + 'h old' };
}

function checkWf16Fresh() {
  for (const sf of RECONCILE_STATE_FILES) {
    const s = safeStat(sf);
    if (!s) continue;
    const ageMin = (nowMs() - s.mtimeMs) / 60_000;
    return { name: 'wf16_fresh', ok: ageMin < 120, detail: ageMin.toFixed(0) + ' min old (' + sf + ')' };
  }
  return { name: 'wf16_fresh', ok: false, detail: 'no reconcile state file' };
}

function checkDiskFree() {
  // Without statvfs accessible from JS, fall back to a simple write test:
  // if we can write a small file, disk isn't catastrophically full.
  const probe = path.join(HEALTH_DIR, '_disk_probe');
  try {
    fs.writeFileSync(probe, String(nowMs()));
    fs.unlinkSync(probe);
    return { name: 'disk_writable', ok: true, detail: 'probe wrote+removed cleanly' };
  } catch (e) {
    return { name: 'disk_writable', ok: false, detail: String(e).slice(0, 120) };
  }
}

async function runAllChecks() {
  const checks = [];
  checks.push(await checkN8n());
  checks.push(checkWf15Fresh());
  checks.push(checkWf16Fresh());
  checks.push(checkDiskFree());
  return checks;
}

function latestPriorRun() {
  let names;
  try { names = fs.readdirSync(HEALTH_DIR).filter(f => f.endsWith('.json') && !f.startsWith('_')).sort(); } catch (_) { return null; }
  for (let i = names.length - 1; i >= 0; i--) {
    const r = safeReadJson(path.join(HEALTH_DIR, names[i]));
    if (r) return r;
  }
  return null;
}

function severityFor(name) {
  if (name === 'n8n_health' || name === 'disk_writable') return 'CRITICAL';
  if (name === 'wf15_fresh' || name === 'wf16_fresh') return 'HIGH';
  return 'MEDIUM';
}

async function pushNtfy(title, body, priority, tags) {
  return new Promise(resolve => {
    const data = body;
    const opts = {
      host: NTFY_HOST,
      port: NTFY_PORT,
      path: '/' + NTFY_TOPIC,
      method: 'POST',
      headers: {
        'Title': title,
        'Priority': String(priority),
        'Tags': (tags || []).join(','),
        'Content-Type': 'text/plain'
      },
      timeout: 5000
    };
    const req = http.request(opts, res => { resolve({ ok: res.statusCode < 400, status: res.statusCode }); });
    req.on('error', () => resolve({ ok: false }));
    req.on('timeout', () => { req.destroy(); resolve({ ok: false, timeout: true }); });
    req.write(data);
    req.end();
  });
}

const results = await runAllChecks();
const prior = latestPriorRun();
const priorByName = (prior && prior.results) ? Object.fromEntries(prior.results.map(r => [r.name, r])) : {};
const priorAlertsByName = (prior && prior.last_alerts) || {};

const alerts = [];
const nowMsLocal = nowMs();
for (const r of results) {
  const wasOk = priorByName[r.name] ? priorByName[r.name].ok : true;
  if (!r.ok && wasOk) {
    alerts.push({ ...r, severity: severityFor(r.name), transition: 'failing' });
  } else if (r.ok && !wasOk) {
    alerts.push({ ...r, severity: 'INFO', transition: 'resolved' });
  } else if (!r.ok && (!priorAlertsByName[r.name] || (nowMsLocal - priorAlertsByName[r.name]) > 6 * 3600_000)) {
    alerts.push({ ...r, severity: severityFor(r.name), transition: 'reminder-6h' });
  }
}

// Track last_alerts timestamps for the next run.
const lastAlerts = { ...priorAlertsByName };
for (const a of alerts) {
  if (a.transition !== 'resolved') lastAlerts[a.name] = nowMsLocal;
}

// Push ntfy notifications for any alerts.
const PRIORITY = { CRITICAL: 5, HIGH: 4, MEDIUM: 3, INFO: 2 };
const TAGS_FAILING = { CRITICAL: ['rotating_light'], HIGH: ['warning'], MEDIUM: ['wrench'], INFO: ['information_source'] };
for (const a of alerts) {
  const title = '[' + a.severity + '] ' + (a.transition === 'resolved' ? 'RESOLVED: ' : '') + a.name;
  const body = a.detail + ' · at ' + now();
  await pushNtfy(title, body, PRIORITY[a.severity] || 3, TAGS_FAILING[a.severity] || ['wrench']);
}

const record = {
  ran_at: now(),
  results,
  alerts,
  last_alerts: lastAlerts
};
const safeTs = record.ran_at.replace(/[:.]/g, '-');
try { fs.writeFileSync(path.join(HEALTH_DIR, safeTs + '.json'), JSON.stringify(record, null, 2)); } catch (_) {}

// Prune health files older than 14 days to keep dir tidy.
try {
  const cutoff = nowMsLocal - 14 * 86400_000;
  for (const f of fs.readdirSync(HEALTH_DIR)) {
    if (!f.endsWith('.json') || f.startsWith('_')) continue;
    const p = path.join(HEALTH_DIR, f);
    const s = safeStat(p);
    if (s && s.mtimeMs < cutoff) try { fs.unlinkSync(p); } catch (_) {}
  }
} catch (_) {}

return [{ json: { ran_at: record.ran_at, ok_count: results.filter(r => r.ok).length, fail_count: results.filter(r => !r.ok).length, alerts: alerts.length, results } }];
